import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s<>"]+|www\.[^\s<>"]+'
    urls = re.findall(url_pattern, myString)
    domains = {}
    for url in urls:
        try:
            parsed = urllib.parse.urlparse(url)
            if parsed.netloc:
                domain = parsed.netloc
            else:
                domain = parsed.path.split('/')[0]
            if domain.startswith('www.'):
                domain = domain[4:]
            domains[domain] = None
        except Exception:
            continue
    result = {}
    for domain in domains:
        try:
            response = requests.get(f"http://ip-api.com/json/{domain}?fields=status,country,region,city,lat,lon,isp,org,as,query&access_key={API_KEY}")
            data = response.json()
            if data.get('status') == 'success':
                result[domain] = data
            else:
                result[domain] = None
        except Exception:
            result[domain] = None
    return result
